style.css:
@-moz-document domain("voz.vn") {
/* ============================================================
     voz.vn Dark
     VOZ runs XenForo 2.x, whose entire skin is driven by HSL
     design tokens stored as "H,S%,L%,A" component strings and
     consumed via hsla(var(--xf-token)). Re-authoring the core
     semantic tokens (content/border/text/link/chrome/input)
     reskins almost the whole component library at the source.
     Element-level rules below mop up the handful of hardcoded
     surfaces (header chrome, code blocks, scrollbars, the rich
     editor) and re-establish opaque dark backgrounds on every
     floating surface (menus, tooltips, sticky nav).
     ============================================================ */

  :root {
    color-scheme: dark !important;
    --xf-styleType: dark !important;
    --xf-color-adjust: -1 !important;

    /* ---- Content surfaces (light original -> dark) ---- */
    /* base page */
    --xf-pageBg:              213, 18%, 9%, 1 !important;   /* #14181d-ish, deepest */
    /* card / block / message background */
    --xf-contentBg:           214, 16%, 14%, 1 !important;  /* ~#1e242c */
    --xf-contentAltBg:        214, 15%, 17%, 1 !important;  /* ~#252b34 user cell / zebra */
    --xf-contentHighlightBg:  214, 30%, 22%, 1 !important;  /* selected / highlight row */
    --xf-contentAccentBg:     24, 45%, 20%, 1 !important;   /* orange accent, toned for dark */

    /* ---- Borders ---- */
    --xf-borderColor:         214, 14%, 22%, 1 !important;  /* ~#2d333b */
    --xf-borderColorLight:    214, 13%, 26%, 1 !important;
    --xf-borderColorHeavy:    214, 14%, 18%, 1 !important;
    --xf-borderColorFaint:    214, 14%, 20%, 1 !important;

    /* ---- Text ---- */
    --xf-textColor:           213, 30%, 92%, 1 !important;  /* #e6edf3 */
    --xf-textColorMuted:      212, 12%, 66%, 1 !important;  /* readable muted grey, also on the elevated #273649 member header */
    --xf-textColorDimmed:     212, 11%, 66%, 1 !important;  /* keep dimmed legible */
    --xf-textColorEmphasized: 213, 32%, 90%, 1 !important;
    --xf-minorHeadingTextColor: 212, 14%, 72%, 1 !important;
    --xf-majorHeadingTextColor: 213, 30%, 92%, 1 !important;

    /* ---- Links / accents ---- */
    /* Text that sits on --xf-contentAccentBg (the "tin tức" prefix chip, the
       accent user banner, important block messages). Left at the site's
       #ff6600 it scores 4.25:1 on the darkened accent surface — lift it. */
    --xf-textColorAccentContent: 24, 100%, 72%, 1 !important;
    --xf-linkColor:           205, 72%, 64%, 1 !important;  /* #5fb0e6 */
    --xf-linkHoverColor:      208, 100%, 80%, 1 !important; /* #9bd4ff */
    --xf-linkUgcColor:        205, 72%, 64%, 1 !important;
    --xf-linkUgcHoverColor:   208, 100%, 80%, 1 !important;
    --xf-textColorFeature:    205, 72%, 64%, 1 !important;

    /* ---- Header / nav chrome (deep, opaque) ---- */
    --xf-chromeBg:            216, 28%, 8%, 1 !important;   /* ~#0d1117 */
    --xf-chromeTextColor:     205, 60%, 72%, 1 !important;  /* light blue nav text */
    --xf-publicHeaderAdjustColor: 0, 0%, 100%, 0.06 !important;
    --xf-subNavBg:            214, 16%, 14%, 1 !important;
    --xf-subNavTextColor:     205, 72%, 64%, 1 !important;

    /* ---- Inputs ---- */
    --xf-inputBgColor:        216, 18%, 12%, 1 !important;
    --xf-inputFocusBgColor:   216, 18%, 15%, 1 !important;
    --xf-inputTextColor:      213, 30%, 92%, 1 !important;

    /* ---- Buttons ---- */
    --xf-buttonBg:            214, 16%, 20%, 1 !important;
    --xf-buttonTextColor:     205, 72%, 70%, 1 !important;
    --xf-buttonCtaBg:         24, 70%, 52%, 1 !important;   /* VOZ orange CTA, toned */
    --xf-buttonPrimaryBg:     205, 65%, 45%, 1 !important;

    /* ---- Block headers / footers / tabs ---- */
    --xf-blockTabHeaderBg:        214, 16%, 14%, 1 !important;
    --xf-blockTabHeaderTextColor: 212, 14%, 72%, 1 !important;
    --xf-blockFooterBg:           214, 15%, 12%, 1 !important;
    --xf-blockFooterTextColor:    212, 11%, 62%, 1 !important;
    --xf-majorHeadingBg:          214, 18%, 11%, 1 !important;

    /* ---- Palette neutrals (used by misc components) ---- */
    --xf-paletteNeutral1:     214, 16%, 14%, 1 !important;
    --xf-paletteNeutral2:     212, 12%, 66%, 1 !important;
    --xf-paletteNeutral3:     213, 30%, 92%, 1 !important;
    --xf-paletteColor1:       214, 30%, 22%, 1 !important;

    /* ---- Editor (rich text reply) ---- */
    --xf-editorBg:            216, 18%, 12%, 1 !important;
    --xf-editorColor:         213, 30%, 92%, 1 !important;
    --xf-editorFocusBg:       216, 18%, 14%, 1 !important;
    --xf-editorFocusColor:    213, 30%, 92%, 1 !important;
    --xf-editorButtonColor:   212, 12%, 66%, 1 !important;
    --xf-editorButtonHoverBg: 214, 16%, 20%, 1 !important;
    --xf-editorButtonHoverColor: 213, 30%, 92%, 1 !important;
    --xf-editorButtonActiveColor: 205, 72%, 64%, 1 !important;
    --xf-editorButtonSelectedBg: 214, 16%, 22%, 1 !important;
    --xf-editorToolsOverflowBg: 216, 18%, 12%, 1 !important;

    /* ---- Selected items / inline-mod ---- */
    --xf-selectedItemBgColor:     214, 30%, 22%, 1 !important;
    --xf-selectedItemColor:       213, 30%, 92%, 1 !important;
    --xf-selectedItemBorderColor: 205, 50%, 40%, 1 !important;
    --xf-inlineModHighlightColor: 24, 45%, 20%, 1 !important;

    /* ---- Avatars / overlay mask ---- */
    --xf-avatarBg:            214, 14%, 22%, 1 !important;
    --xf-overlayMaskColor:    216, 30%, 4%, 0.7 !important;

    /* ---- Semantic colors: preserve, tune lightness for dark ---- */
    --xf-successColor:        130, 50%, 58%, 1 !important;
    --xf-successBg:           130, 30%, 14%, 1 !important;
    --xf-successFeatureColor: 130, 50%, 55%, 1 !important;
    --xf-errorColor:          5, 75%, 68%, 1 !important;
    --xf-errorBg:             5, 35%, 16%, 1 !important;
    --xf-errorFeatureColor:   5, 75%, 65%, 1 !important;
    --xf-warningColor:        38, 80%, 62%, 1 !important;
    --xf-warningBg:           38, 40%, 15%, 1 !important;
    --xf-warningFeatureColor: 38, 80%, 60%, 1 !important;
    --xf-votePositiveColor:   130, 50%, 56%, 1 !important;
    --xf-voteNegativeColor:   5, 75%, 66%, 1 !important;
    --xf-textColorAttention:  38, 80%, 62%, 1 !important;
    --xf-borderColorAttention: 38, 50%, 35%, 1 !important;

    /* ---- Read/unread node icons ---- */
    --xf-nodeIconReadColor:   212, 12%, 40%, 1 !important;
    --xf-nodeIconUnreadColor: 205, 72%, 60%, 1 !important;

    /* ---- Stars ---- */
    --xf-starFullColor:       42, 90%, 58%, 1 !important;
    --xf-starEmptyColor:      214, 12%, 30%, 1 !important;

    /* ============================================================
       Token COMPONENTS.
       Every token above is a convenience alias the skin defines as
       "var(--tok--h), var(--tok--s), var(--tok--l), var(--tok--a)".
       Overriding only the alias covers the plain hsla(var(--tok))
       consumers, but XenForo derives every hover / disabled /
       selected shade with calc() on the SEPARATE component vars
       (calc(var(--tok--l) - (var(--xf-color-adjust) * 10%))).
       Those calcs keep resolving against the LIGHT palette unless
       the components are re-authored too, which is why hovers,
       disabled controls, flash messages and the filter pill kept
       painting near-white on a fully dark page. Only the tokens the
       skin actually consumes componentwise are listed.
       ============================================================ */
    --xf-contentBg--h: 214 !important;
    --xf-contentBg--s: 16% !important;
    --xf-contentBg--l: 14% !important;
    --xf-contentBg--a: 1 !important;

    --xf-contentAltBg--h: 214 !important;
    --xf-contentAltBg--s: 15% !important;
    --xf-contentAltBg--l: 17% !important;
    --xf-contentAltBg--a: 1 !important;

    --xf-contentHighlightBg--h: 214 !important;
    --xf-contentHighlightBg--s: 30% !important;
    --xf-contentHighlightBg--l: 22% !important;
    --xf-contentHighlightBg--a: 1 !important;

    --xf-contentAccentBg--h: 24 !important;
    --xf-contentAccentBg--s: 45% !important;
    --xf-contentAccentBg--l: 20% !important;
    --xf-contentAccentBg--a: 1 !important;

    --xf-borderColor--h: 214 !important;
    --xf-borderColor--s: 14% !important;
    --xf-borderColor--l: 22% !important;
    --xf-borderColor--a: 1 !important;

    --xf-textColor--h: 213 !important;
    --xf-textColor--s: 30% !important;
    --xf-textColor--l: 92% !important;
    --xf-textColor--a: 1 !important;

    --xf-textColorMuted--h: 212 !important;
    --xf-textColorMuted--s: 12% !important;
    --xf-textColorMuted--l: 66% !important;
    --xf-textColorMuted--a: 1 !important;

    --xf-majorHeadingTextColor--h: 213 !important;
    --xf-majorHeadingTextColor--s: 30% !important;
    --xf-majorHeadingTextColor--l: 92% !important;
    --xf-majorHeadingTextColor--a: 1 !important;

    --xf-majorHeadingBg--h: 214 !important;
    --xf-majorHeadingBg--s: 18% !important;
    --xf-majorHeadingBg--l: 11% !important;
    --xf-majorHeadingBg--a: 1 !important;

    --xf-linkColor--h: 205 !important;
    --xf-linkColor--s: 72% !important;
    --xf-linkColor--l: 64% !important;
    --xf-linkColor--a: 1 !important;

    --xf-textColorFeature--h: 205 !important;
    --xf-textColorFeature--s: 72% !important;
    --xf-textColorFeature--l: 64% !important;
    --xf-textColorFeature--a: 1 !important;

    --xf-chromeBg--h: 216 !important;
    --xf-chromeBg--s: 28% !important;
    --xf-chromeBg--l: 8% !important;
    --xf-chromeBg--a: 1 !important;

    --xf-chromeTextColor--h: 205 !important;
    --xf-chromeTextColor--s: 60% !important;
    --xf-chromeTextColor--l: 72% !important;
    --xf-chromeTextColor--a: 1 !important;

    --xf-publicHeaderAdjustColor--h: 0 !important;
    --xf-publicHeaderAdjustColor--s: 0% !important;
    --xf-publicHeaderAdjustColor--l: 100% !important;
    --xf-publicHeaderAdjustColor--a: 6% !important;

    --xf-subNavBg--h: 214 !important;
    --xf-subNavBg--s: 16% !important;
    --xf-subNavBg--l: 14% !important;
    --xf-subNavBg--a: 1 !important;

    --xf-subNavTextColor--h: 205 !important;
    --xf-subNavTextColor--s: 72% !important;
    --xf-subNavTextColor--l: 64% !important;
    --xf-subNavTextColor--a: 1 !important;

    --xf-inputBgColor--h: 216 !important;
    --xf-inputBgColor--s: 18% !important;
    --xf-inputBgColor--l: 12% !important;
    --xf-inputBgColor--a: 1 !important;

    --xf-inputTextColor--h: 213 !important;
    --xf-inputTextColor--s: 30% !important;
    --xf-inputTextColor--l: 92% !important;
    --xf-inputTextColor--a: 1 !important;

    --xf-buttonBg--h: 214 !important;
    --xf-buttonBg--s: 16% !important;
    --xf-buttonBg--l: 20% !important;
    --xf-buttonBg--a: 1 !important;

    --xf-buttonCtaBg--h: 24 !important;
    --xf-buttonCtaBg--s: 70% !important;
    --xf-buttonCtaBg--l: 52% !important;
    --xf-buttonCtaBg--a: 1 !important;

    --xf-buttonPrimaryBg--h: 205 !important;
    --xf-buttonPrimaryBg--s: 65% !important;
    --xf-buttonPrimaryBg--l: 45% !important;
    --xf-buttonPrimaryBg--a: 1 !important;

    --xf-blockTabHeaderBg--h: 214 !important;
    --xf-blockTabHeaderBg--s: 16% !important;
    --xf-blockTabHeaderBg--l: 14% !important;
    --xf-blockTabHeaderBg--a: 1 !important;

    --xf-blockFooterBg--h: 214 !important;
    --xf-blockFooterBg--s: 15% !important;
    --xf-blockFooterBg--l: 12% !important;
    --xf-blockFooterBg--a: 1 !important;

    --xf-avatarBg--h: 214 !important;
    --xf-avatarBg--s: 14% !important;
    --xf-avatarBg--l: 22% !important;
    --xf-avatarBg--a: 1 !important;

    --xf-paletteNeutral1--h: 214 !important;
    --xf-paletteNeutral1--s: 16% !important;
    --xf-paletteNeutral1--l: 14% !important;
    --xf-paletteNeutral1--a: 1 !important;

    --xf-paletteNeutral2--h: 212 !important;
    --xf-paletteNeutral2--s: 12% !important;
    --xf-paletteNeutral2--l: 66% !important;
    --xf-paletteNeutral2--a: 1 !important;

    --xf-paletteNeutral3--h: 213 !important;
    --xf-paletteNeutral3--s: 30% !important;
    --xf-paletteNeutral3--l: 92% !important;
    --xf-paletteNeutral3--a: 1 !important;

    --xf-paletteColor1--h: 214 !important;
    --xf-paletteColor1--s: 30% !important;
    --xf-paletteColor1--l: 22% !important;
    --xf-paletteColor1--a: 1 !important;
  }

  /* ============================================================
     Base surfaces
     ============================================================ */
  html,
  body {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }

  .p-pageWrapper {
    background-color: #14181d !important;
  }

  /* Soften any stray light borders the token sweep misses */
  .block-container,
  .block-row,
  .structItem,
  .message,
  .message-cell,
  .formRow,
  .inputGroup,
  hr,
  .bbCodeBlock {
    border-color: #2d333b !important;
  }

  /* NOTE: no blanket .userBanner border rule. The base chip's border is
     transparent (hsla(0,0%,0%,0)) — a grey border there draws a box the site
     never draws — and every rank variant (.userBanner--red / --green / --blue
     / --staff / …) ships a border-color matched to its own fill, which an
     !important grey would flatten into a clashing outline. */

  /* Hardcoded pure-white borders the --xf-borderColor token never reaches */
  /* XenForo input addons (login "Show" password toggle, search field addons) */
  .inputGroup-text,
  .inputGroup--joined .input {
    border-color: #2d333b !important;
  }

  /* ============================================================
     Header / navigation chrome
     ============================================================ */
  .p-header,
  .p-nav,
  .p-nav-inner,
  .p-nav-list,
  .p-navSticky,
  .p-navSticky.is-sticky,
  .p-navSticky.is-sticky .p-nav {
    background-color: #0d1117 !important;
    border-color: #20262e !important;
  }

  .p-nav-opposite a,
  .p-navEl-link,
  .p-navgroup-link,
  .p-header-content a,
  .p-discovery,
  .p-discovery .bars {
    color: #c4d3e8 !important;
  }

  .p-navEl-link.p-navEl-link--splitMenu .p-navEl-splitTrigger,
  .p-navEl.is-selected > .p-navEl-link,
  .p-navEl-link:hover {
    color: #ffffff !important;
    background-color: rgba(255, 255, 255, 0.06) !important;
  }

  /* Category / block section headers (use a light gradient on the live site) */
  .block-header,
  .block-header.block-header--summary,
  .block-tabHeader,
  .block-minorTabHeader,
  .block-outer-main {
    background-image: linear-gradient(0deg, #161b22, #1c232c) !important;
    background-color: #1a2029 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .block-header a,
  .block-header .block-header-title,
  .block-minorHeader,
  .block-minorHeader a {
    color: #c4d3e8 !important;
  }
  /* block-footer ("View more…" bar) ships the same hardcoded light XenForo
     gradient as the headers — background-color alone can't override it, kill
     the image too */
  .block-footer {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #aab4bf !important;
    border-color: #2d333b !important;
  }

  /* Content tab bars (member profile "Profile posts / Latest activity / …",
     forum tab headers): the ACTIVE tab keeps a hardcoded dark navy text
     (#273649) readable only on the light original — make it light on dark */
  .tabs-tab,
  .block-tabHeader .tabs-tab {
    color: #c4d3e8 !important;
  }
  .tabs-tab.is-active,
  .block-tabHeader .tabs-tab.is-active {
    color: #ffffff !important;
  }

  /* Section links bar under header */
  .p-sectionLinks {
    background-color: #161b22 !important;
    border-color: #20262e !important;
  }
  .p-sectionLinks-list > li > a {
    color: #c4d3e8 !important;
  }
  .p-sectionLinks-list > li.is-selected > a {
    color: #ffffff !important;
    background-color: #1c232c !important;
  }

  /* Header search box / navgroup */
  .p-navgroup--member .p-navgroup-link--icon,
  .p-navgroup .p-navgroup-link {
    color: #c4d3e8 !important;
  }

  /* ============================================================
     Floating surfaces — must stay OPAQUE (no bleed-through)
     ============================================================ */
  .menu,
  .menu-content,
  .tooltip-content,
  .overlay,
  .overlay-container,
  .blockMessage,
  .autoComplete,
  .acp-menu,
  .js-headerOffsetTarget .menu {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Menu header/footer carry a hardcoded light silver gradient
     (linear-gradient(0deg, #273649, #dbe6f5)) that background-color
     alone can't override — kill the image too */
  .menu-header {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .menu-footer,
  .menu-footer-controls {
    background-image: none !important;
    background-color: #161b22 !important;
    border-color: #2d333b !important;
  }
  .menu-row:hover,
  .menu-linkRow:hover {
    background-color: #232a33 !important;
  }
  /* The style-variation chooser previews each variation by re-scoping the XenForo
     palette on its rows, so the currently-selected row resolves
     --xf-contentHighlightBg against the LIGHT variation (l=96%) and paints a
     bright band our :root token override never reaches. Paint the selected row
     directly; the VOZ-orange text stays as the "selected" signal. */
  .menu-row.is-selected,
  a.menu-linkRow.is-selected,
  .menu-linkRow.is-selected {
    background-color: #232a33 !important;
  }
  .tooltip-content {
    box-shadow: 0 1px 6px rgba(0, 0, 0, 0.6) !important;
  }
  /* A tooltip's caret is a border triangle painted on the ARROW ELEMENT
     itself (not a pseudo), coloured from a light token — it renders as a
     pale grey nib hanging off a dark bubble. This applies to EVERY tooltip
     flavour (basic, member hover-card, share), so key off the direction
     modifier alone rather than .tooltip--basic. */
  .tooltip--top .tooltip-arrow {
    border-top-color: #1c2128 !important;
  }
  .tooltip--bottom .tooltip-arrow {
    border-bottom-color: #1c2128 !important;
  }
  .tooltip--left .tooltip-arrow {
    border-left-color: #1c2128 !important;
  }
  .tooltip--right .tooltip-arrow {
    border-right-color: #1c2128 !important;
  }

  /* Menus are topped by a 3px feature-blue rule and the .menu-arrow caret is
     that rule's tip. The blanket border-color above greys the rule but cannot
     reach the caret (it keeps painting #3c79c8), leaving an orphaned blue
     triangle over a flat grey edge — restore the blue rule instead. */
  .menu-content {
    border-top-color: #3c79c8 !important;
  }

  /* ============================================================
     Inputs / forms / placeholders
     ============================================================ */
  .input,
  .input--date,
  select,
  textarea,
  .js-editor,
  .contentRow input,
  .formRow input {
    background-color: #11161c !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .input:focus,
  textarea:focus,
  select:focus {
    background-color: #161b22 !important;
    border-color: #3d6a96 !important;
  }
  ::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }
  .input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* Password-strength meter (register/password change): native <meter>
     track renders bright white on dark — darken the bar, keep value colors */
  meter,
  .meterBar {
    background: #11161c !important;
    border: 1px solid #2d333b !important;
    border-radius: 6px !important;
  }
  meter::-webkit-meter-bar {
    background: #11161c !important;
    border: none !important;
    border-radius: 6px !important;
  }

  /* Rich-text reply editor (Froala + VOZ's RTE Write/Preview tabs):
     the editor chrome ships hardcoded white/light borders, a light
     toolbar separator (.fr-newline) and a dark-on-dark placeholder
     (rgba(29,31,32,0.4)) that the XenForo editor tokens never reach */
  .fr-box.bbWrapper,
  .fr-second-toolbar {
    background-color: #191d24 !important;
    border-color: #2d333b !important;
  }
  .fr-toolbar,
  .fr-btn-grp,
  .fr-newline,
  .fr-box .rte-tab,
  .fr-box [class*="rte-tab"] {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  .fr-placeholder {
    color: #8b949e !important;
  }

  /* Buttons */
  .button,
  .buttonGroup,
  .menuTrigger {
    background-color: #21262d !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .button:hover {
    background-color: #2a313a !important;
    color: #ffffff !important;
  }
  .button.button--cta,
  .button--cta {
    background-image: none !important;
    background-color: #d4691e !important;
    color: #ffffff !important;
    border-color: #d4691e !important;
  }
  .button.button--cta:hover {
    background-color: #e2792c !important;
  }

  /* The neutral `.button` rule above carries !important, so it also swallows
     every XenForo button VARIANT (all of which style themselves without
     !important). Restore each one, otherwise the primary submit, the
     borderless link buttons and the mobile nav trigger all render as the
     same anonymous grey box. */
  /* Primary submit ("Log in", "Save") — the page's main action, keep it blue */
  .button.button--primary,
  a.button.button--primary {
    background-color: #287fbd !important;
    color: #ffffff !important;
    border-color: #287fbd !important;
  }
  .button.button--primary:hover,
  a.button.button--primary:hover {
    background-color: #3390cf !important;
  }
  /* Borderless, link-coloured button (mobile nav trigger, inline actions) */
  .button.button--plain,
  a.button.button--plain {
    background-color: transparent !important;
    border-color: transparent !important;
    color: #5fb0e6 !important;
  }
  .button.button--plain:hover,
  a.button.button--plain:hover {
    background-color: transparent !important;
    color: #9bd4ff !important;
  }
  /* Quiet "button that reads as a link" (the logged-out reply bar) */
  .button.button--link,
  a.button.button--link {
    background-color: #1e242c !important;
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }
  .button.button--link:hover,
  a.button.button--link:hover {
    background-color: #253039 !important;
  }
  /* Disabled must not look identical to enabled */
  .button.is-disabled,
  a.button.is-disabled,
  .button.is-disabled:hover,
  a.button.is-disabled:hover {
    background-color: #1a1e24 !important;
    color: #6a737d !important;
    border-color: #23282f !important;
  }

  /* ============================================================
     Thread list (structItem) / forum nodes
     ============================================================ */
  /* Sort/filter bar above the thread list ships a hardcoded light-blue
     gradient (linear-gradient(0deg, #273649, #dbe6f5)) the token sweep misses */
  .block-filterBar {
    background-image: linear-gradient(0deg, #161b22, #1c232c) !important;
    background-color: #1a2029 !important;
    color: #c4d3e8 !important;
    border-color: #2d333b !important;
  }
  .structItem--thread:hover,
  .structItem.is-selected {
    background-color: #1c232c !important;
  }
  .structItem-minor,
  .structItem-parts,
  .structItem-pageJump a,
  .structItem-cell--latest .structItem-minor {
    color: #aab4bf !important;
  }
  .structItem-cell--meta dt {
    color: #8b949e !important;
  }
  .structItem-cell--meta dd {
    color: #c4cdd6 !important;
  }
  .node-extra,
  .node-meta,
  .node-statsMeta,
  .node-descriptionText,
  .nodeList .node-extra-row {
    color: #aab4bf !important;
  }

  /* ============================================================
     Messages / posts
     ============================================================ */
  .message-cell--user {
    background-color: #181d24 !important;
  }
  .message-name .username,
  .message-name a {
    color: #e6edf3 !important;
  }
  .message-userTitle,
  .message-userExtras dd,
  .message-attribution,
  .message-attribution-main a,
  .message-attribution-opposite,
  .message-attribution-opposite a {
    color: #9aa4af !important;
  }
  .bbWrapper {
    color: #c8d1da !important;
  }
  /* Posts frequently hardcode pure-black text via the BBCode colour picker
     (readable on the original light theme, invisible on dark). Only pure
     black is ever a light-theme artifact — remap it to the body text colour
     while leaving every other author colour (reds, blues, greens) intact.
     The 3-digit "#000" form is deliberately omitted: it is a substring of
     "#0000ff" etc. and would clobber intentional blues. */
  .bbWrapper [style*="color: rgb(0, 0, 0)"],
  .bbWrapper [style*="color:rgb(0,0,0)"],
  .bbWrapper [style*="color: #000000"],
  .bbWrapper [style*="color:#000000"],
  .bbWrapper [style*="color: black"],
  .bbWrapper [style*="color:black"] {
    color: #c8d1da !important;
    -webkit-text-fill-color: #c8d1da !important;
  }

  /* Quotes */
  blockquote.bbCodeBlock,
  .bbCodeBlock--quote,
  .bbCodeBlock-title,
  .bbCodeQuote-source {
    background-color: #181d24 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* The attribution line ("<user> said:" + the jump-to-source arrow) is VOZ
     orange, not body text — the rule above flattened it into the quoted text
     and the quote lost its header. */
  .bbCodeBlock-title,
  .bbCodeBlock-title a,
  a.bbCodeBlock-sourceJump {
    color: #ff944d !important;
  }
  /* .bbCodeBlock-expandLink is a 400px-tall position:absolute overlay sitting
     ON TOP of the collapsed quote; natively its background-color is
     transparent and only a fade gradient paints. Giving it an opaque colour
     blanks 400px of the quoted post. Keep it transparent and re-aim the
     gradient at the quote background so the fade lands on the right colour. */
  .bbCodeBlock-expandLink {
    background-color: transparent !important;
    background-image: linear-gradient(to bottom, rgba(24, 29, 36, 0) 0%, #181d24 80%) !important;
  }
  .bbCodeBlock-expandLink a {
    background-color: transparent !important;
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Code blocks + syntax (light tokens are unreadable on dark)
     ============================================================ */
  .bbCodeCode,
  .bbCodeBlock--code,
  .bbCodeBlock--code .bbCodeBlock-content,
  pre,
  code,
  kbd,
  .code {
    background-color: #0d1117 !important;
    color: #c9d1d9 !important;
    border-color: #2d333b !important;
  }
  /* GeSHi / prettify syntax palette */
  .bbCodeCode .token.comment,
  .prettyprint .com,
  .syntaxhighlighter .comments {
    color: #8b949e !important;
  }
  .prettyprint .kwd,
  .prettyprint .tag {
    color: #ff7b72 !important;
  }
  .prettyprint .str,
  .prettyprint .atv {
    color: #a5d6ff !important;
  }
  .prettyprint .lit,
  .prettyprint .dec {
    color: #79c0ff !important;
  }
  .prettyprint .typ,
  .prettyprint .atn {
    color: #d2a8ff !important;
  }
  .prettyprint .pun,
  .prettyprint .pln {
    color: #c9d1d9 !important;
  }

  /* ============================================================
     Pagination / breadcrumbs / reactions
     ============================================================ */
  .pageNav-page a {
    background-color: #1c2128 !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .pageNav-page:hover a {
    background-color: #262d36 !important;
  }
  .pageNav-page--current a,
  .pageNav-page--current {
    background-color: #d4691e !important;
    color: #ffffff !important;
    border-color: #d4691e !important;
  }
  /* Narrow viewports swap the numbered pager for .pageNavSimple ("1 of 8687").
     It is a separate component, so it never inherited the orange current-page
     chip above and fell back to the muted brown accent token instead. */
  .pageNavSimple-el--current {
    background-color: #d4691e !important;
    color: #ffffff !important;
    border-color: #d4691e !important;
  }
  .p-breadcrumbs li,
  .p-breadcrumbs a,
  .breadcrumb a {
    color: #aab4bf !important;
  }
  .p-breadcrumbs:before,
  .p-description {
    color: #8b949e !important;
  }

  .reactionsBar,
  .reactionSummary,
  .message-lastEdit {
    background-color: #181d24 !important;
    color: #9aa4af !important;
    border-color: #2d333b !important;
  }
  /* The reactions bar's identity is a blue 2px left rule (borderColorFeature);
     the blanket border-color above erases it. */
  .reactionsBar {
    border-left-color: #3c79c8 !important;
  }

  /* Tags. `.label` is deliberately NOT flattened here: on VOZ every thread
     PREFIX is a `.label--red / --orange / --royalBlue / --primary / …` chip
     and those modifiers carry no !important, so a neutral `.label` rule with
     !important collapses the whole prefix vocabulary into one grey pill.
     The bare `.label` has a transparent background of its own, and the
     token-driven modifiers now resolve dark through the components above. */
  .tagItem {
    background-color: #21262d !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Footer
     ============================================================ */
  .p-footer,
  .p-footer-inner,
  .p-footer-row {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-color: #20262e !important;
  }
  .p-footer a,
  .p-footer-linkList a {
    color: #aab4bf !important;
  }

  /* ============================================================
     Misc surfaces
     ============================================================ */
  .blockLink,
  .subHeading,
  .dataList-row:hover,
  .block-outer-opposite {
    background-color: transparent !important;
  }
  .blockStatus,
  .notice {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Sticky form submit bar (login / search / post reply) + overlay
     titles also ship the light XenForo gradient — neutralize the image */
  .formSubmitRow-bar,
  .formSubmitRow,
  .menu-footer,
  .overlay-title {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .overlay-title {
    background-color: #0d1117 !important;
  }

  /* Avatar / image wrappers (avoid white tiles behind images). Exclude the
     letter avatars (.avatar--default--dynamic): those carry a per-user inline
     background-color (#33cc66 …) that IS the disc, with a matching dark letter
     colour — forcing them transparent drops the disc and leaves an invisible
     dark-on-dark initial. Keep their inline colour intact. */
  .avatar:not(.avatar--default),
  .avatarWrapper,
  .contentRow-figure,
  .structItem-iconContainer {
    background-color: transparent !important;
  }

  /* Ad wrappers ship a light/white container background that shows as grey
     bands around the (centered) ad — darken the wrapper, leave ad content */
  .ad-wrapper-sticky,
  .power_stickybanner__wrapper,
  .adsbypubpower {
    background-color: #14181d !important;
  }
  /* PubPower's sticky-banner collapse toggle is a separate, class-less element
     with an inline white (#fafafa !important) background, a white SVG face
     (rect + path) and a dark chevron — a glaring white pill at the page edge,
     most visible on mobile. Inline !important background-color can't be beaten
     by an external rule, so repaint via background-image; darken the SVG face
     and lighten the chevron lines so the control stays legible on dark. The id
     carries a volatile numeric suffix, so match on the stable prefix. */
  [id^="close_stickybanner"] {
    background-image: linear-gradient(#1c2128, #1c2128) !important;
    border-top-color: #2d333b !important;
    box-shadow: none !important;
  }
  [id^="close_stickybanner"] svg rect,
  [id^="close_stickybanner"] svg path {
    fill: #1c2128 !important;
    stroke: #1c2128 !important;
  }
  [id^="close_stickybanner"] svg line {
    stroke: #c4d3e8 !important;
  }

  /* Scrollbar */
  * {
    scrollbar-color: #2d333b #14181d;
  }
  ::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }
  ::-webkit-scrollbar-track {
    background: #14181d;
  }
  ::-webkit-scrollbar-thumb {
    background: #2d333b;
    border-radius: 6px;
    border: 2px solid #14181d;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #3a424c;
  }

  /* Text selection */
  ::selection {
    background: #2f5a86;
    color: #ffffff;
  }
}
